import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(c));

        // Give the contract some ETH to send as rewards
        vm.deal(address(c), 200);

        // Record the recipient's initial balance
        uint initialBalance = recipient.balance;

        // Call getFirstWithdrawalBonus
        (bool ok, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient));
        require(ok, "getFirstWithdrawalBonus reverted");

        // The recipient must have received either 100 (if the call succeeded) or 0 (if the call failed)
