pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.deal(address(c), 100 ether);

        // Call getFirstWithdrawalBonus once
        (bool success1, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient));
        // The call might revert if claimedBonus already set, but we assume a fresh address
        if (!success1) return; // skip if already claimed (but we assume not)

        // Now call withdrawReward again for the same recipient
        (bool success2, ) = address(c).call(abi.encodeWithSignature("withdrawReward(address)", recipient));

        // In the reference, the second withdraw should revert because rewardsForA[recipient] is 0 after withdrawal
        // In the bug, the second withdraw also reverts because the reentrancy lock is missing and the call fails differently
        // But both revert, so we need a different property:
        // Instead, after getFirstWithdrawalBonus, the recipient's balance should increase by 100
        // But we cannot read recipient.balance? We can via address(recipient).balance

        // Actually the correct property: after getFirstWithdrawalBonus(recipient), the reward is sent, so recipient.balance increases by 100
        uint256 balanceBefore = recipient.balance;
        (bool ok, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient));
        require(ok);
        uint256 balanceAfter = recipient.balance;

        assertTrue(balanceAfter == balanceBefore + 100, "balance should increase by 100");
    }
}

