pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(c));
        // Call getFirstWithdrawalBonus(recipient)
        // It will either succeed or revert; we only care about the case where it doesn't revert
        // because the bug is observable only after a successful call
        try c.getFirstWithdrawalBonus(recipient) {
            // If it succeeds, then rewardsForA[recipient] must be 0
            // We need a getter for rewardsForA. The original contract has it private, so we rely on the fact
            // that after successful call, the reward is withdrawn. But we cannot read private state directly.
            // However, the difference is about the _locked variable being reset.
            // The rule: after a successful call to getFirstWithdrawalBonus(recipient), the contract should NOT be locked.
            // But that rule was already tried. Let's think differently: 
            // The bug is that _locked stays true forever after first call. So after a successful call,
            // any subsequent call that requires !_locked will revert.
            // So we can test: after calling getFirstWithdrawalBonus, a call to withdrawReward with a different address should revert.
            // But withdrawReward is external. We need to see if it reverts.
            // Actually, the simpler rule: after getFirstWithdrawalBonus, calling getFirstWithdrawalBonus again for the same address should revert (because claimedBonus is true).
            // That's not related to the bug.
            // The actual bug: _locked remains true, so any reentrant call will revert.
            // So after a successful getFirstWithdrawalBonus, calling it again for a DIFFERENT address should revert.
        } catch {
            // ignore reverts
        }
    }
}

