import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(c));
        // Ensure recipient has no bonus claimed yet
        // We use vm.assume to constrain to addresses where claimedBonus is false
        // But we cannot read private mapping directly; instead we rely on the fact that
        // for a fresh address, claimedBonus[recipient] is false by default
        // and we only call once
        c.getFirstWithdrawalBonus(recipient);
        // The general rule: after calling getFirstWithdrawalBonus, the bonus is claimed
        // We check via the public getter of claimedBonus? No, it's private.
        // Actually we know _locked state shows that the call succeeded.
        // The only observable public state difference is that _locked is false again.
        // But there's no public getter for claimedBonus. 
        // The difference is that in P, subsequent call reverts; in M it succeeds.
        // So the rule: calling getFirstWithdrawalBonus twice with same recipient reverts on P but not on M
        // Let's try that:
        bool reverted = false;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted, "Second call should revert, meaning bonus was claimed");
    }
