pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        // We need to check the state before and after, but we cannot read private mapping directly.
        // Use a try-catch to detect revert if the bonus was already claimed.
        // The rule: after successfully calling getFirstWithdrawalBonus, a second call should revert.

        // First call may succeed or revert if already claimed
        (bool success1, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient));
        // If first call succeeded, then second call must revert
        if (success1) {
            (bool success2, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient));
            assertTrue(!success2, "Second call should revert when bonus already claimed");
        } else {
            // First call reverted, meaning the bonus was already claimed earlier, so rule vacuously holds
            assertTrue(true);
        }
    }
}

